419: // flushWithCallback sends any outstanding telemetry messages and aggregated metrics to be
420: // sent to the backend. Requests are sent in the background and a callback is called after the flush finishes.
421: // Must be called with c.mu locked
422: func (c *client) flushWithCallback(callback func()) {
423: 	// initialize submissions slice of capacity len(c.requests) + 2
424: 	// to hold all the new events, plus two potential metric events
425: 	submissions := make([]*Request, 0, len(c.requests)+2)
426: 
427: 	// copy over requests so we can do the actual submission without holding
428: 	// the lock. Zero out the old stuff so we don't leak references
429: 	for i, r := range c.requests {
430: 		submissions = append(submissions, r)
431: 		c.requests[i] = nil
432: 	}
433: 	c.requests = c.requests[:0]
434: 
435: 	if c.newMetrics {
436: 		c.newMetrics = false
437: 		for namespace := range c.metrics {
438: 			// metrics can either be request type generate-metrics or distributions
439: 			dPayload := &DistributionMetrics{
440: 				Namespace: namespace,
441: 			}
442: 			gPayload := &Metrics{
443: 				Namespace: namespace,
444: 			}
445: 			for _, m := range c.metrics[namespace] {
446: 				if m.kind == MetricKindDist {
447: 					dPayload.Series = append(dPayload.Series, DistributionSeries{
448: 						Metric: m.name,
449: 						Tags:   m.tags,
450: 						Common: m.common,
451: 						Points: []float64{m.value},
452: 					})
453: 				} else {
454: 					gPayload.Series = append(gPayload.Series, Series{
455: 						Metric: m.name,
456: 						Type:   string(m.kind),
457: 						Tags:   m.tags,
458: 						Common: m.common,
459: 						Points: [][2]float64{{m.ts, m.value}},
460: 					})
461: 				}
462: 			}
463: 			if len(dPayload.Series) > 0 {
464: 				distributions := c.newRequest(RequestTypeDistributions)
465: 				distributions.Body.Payload = dPayload
466: 				submissions = append(submissions, distributions)
467: 			}
468: 			if len(gPayload.Series) > 0 {
