550: // submit sends a telemetry request
551: func (r *Request) submit() error {
552: 	retry, err := r.trySubmit()
553: 	if retry {
554: 		// retry telemetry submissions in instances where the telemetry client has trouble
555: 		// connecting with the agent
556: 		log("telemetry submission failed, retrying with agentless: %s", err)
557: 		r.URL = getAgentlessURL()
558: 		r.Header.Set("DD-API-KEY", defaultAPIKey())
559: 		if _, err := r.trySubmit(); err == nil {
560: 			return nil
561: 		}
562: 		log("retrying with agentless telemetry failed: %s", err)
563: 	}
564: 	return err
565: }
