567: // agentlessRetry determines if we should retry a failed a request with
568: // by submitting to the agentless endpoint
569: func agentlessRetry(req *Request, resp *http.Response, err error) bool {
570: 	if req.URL == getAgentlessURL() {
571: 		// no need to retry with agentless endpoint if it already failed
572: 		return false
573: 	}
574: 	if err != nil {
575: 		// we didn't get a response which might signal a connectivity problem with
576: 		// agent - retry with agentless
577: 		return true
578: 	}
579: 	// TODO: add more status codes we do not want to retry on
580: 	doNotRetry := []int{http.StatusBadRequest, http.StatusTooManyRequests, http.StatusUnauthorized, http.StatusForbidden}
581: 	for status := range doNotRetry {
582: 		if resp.StatusCode == status {
583: 			return false
584: 		}
585: 	}
586: 	return true
587: }
