589: // trySubmit submits a telemetry request to the specified URL
590: // in the Request struct. If submission fails, return whether or not
591: // this submission should be re-tried with the agentless endpoint
592: // as well as the error that occurred
593: func (r *Request) trySubmit() (retry bool, err error) {
594: 	b, err := json.Marshal(r.Body)
595: 	if err != nil {
596: 		return false, err
597: 	}
598: 
599: 	req, err := http.NewRequest(http.MethodPost, r.URL, bytes.NewReader(b))
600: 	if err != nil {
601: 		return false, err
602: 	}
603: 	req.Header = *r.Header
604: 
605: 	req.ContentLength = int64(len(b))
606: 
607: 	client := r.HTTPClient
608: 	if client == nil {
609: 		client = defaultHTTPClient
610: 	}
611: 	resp, err := client.Do(req)
612: 	if err != nil {
613: 		return agentlessRetry(r, resp, err), err
614: 	}
615: 	defer resp.Body.Close()
616: 	if resp.StatusCode != http.StatusAccepted && resp.StatusCode != http.StatusOK {
617: 		return agentlessRetry(r, resp, err), errBadStatus(resp.StatusCode)
618: 	}
619: 	return false, nil
620: }
