299: // Stop notifies the telemetry endpoint that the app is closing. All outstanding
300: // messages will also be sent. No further messages will be sent until the client
301: // is started again
302: func (c *client) Stop() {
303: 	c.mu.Lock()
304: 	defer c.mu.Unlock()
305: 	if !c.started {
306: 		return
307: 	}
308: 	c.started = false
309: 	c.heartbeatT.Stop()
310: 	// close request types have no body
311: 	r := c.newRequest(RequestTypeAppClosing)
312: 	c.scheduleSubmit(r)
313: 	if c.syncFlushOnStop || internal.BoolEnv("DD_CIVISIBILITY_ENABLED", false) {
314: 		cnn := make(chan struct{})
315: 		c.flushWithCallback(func() {
316: 			cnn <- struct{}{}
317: 			close(cnn)
318: 		})
319: 		<-cnn
320: 	} else {
321: 		c.flush()
322: 	}
323: }
